package pe.ganadoconecta.modulos.reproduccion.adaptadores.entrada.http;
import java.time.*;import java.util.*;import org.springframework.context.annotation.Profile;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
import pe.ganadoconecta.modulos.identidad.adaptadores.entrada.http.IdentidadAutenticada;import pe.ganadoconecta.modulos.reproduccion.aplicacion.*;import pe.ganadoconecta.modulos.reproduccion.dominio.*;
@RestController @Profile("postgres") @RequestMapping("/api/v1/ganaderias/{ganaderiaId}/animales/{animalId}/eventos-reproductivos")
public class ReproduccionControlador{
 private final RegistrarEventoReproductivo registrar;private final ListarEventosReproductivos listar;public ReproduccionControlador(RegistrarEventoReproductivo r,ListarEventosReproductivos l){registrar=r;listar=l;}
 @PostMapping ResponseEntity<Resultado> registrar(@PathVariable UUID ganaderiaId,@PathVariable UUID animalId,@RequestBody Solicitud b,@AuthenticationPrincipal IdentidadAutenticada i){var x=registrar.ejecutar(b.dominio(ganaderiaId,animalId),i.usuarioId(),i.sesionId());return ResponseEntity.status(x.estado()==ResultadoEventoReproductivo.Estado.APLICADO?201:200).cacheControl(CacheControl.noStore()).body(new Resultado(x.operationId(),x.eventId(),x.estado().name(),x.confirmadoEn()));}
 @GetMapping ResponseEntity<List<Evento>> listar(@PathVariable UUID ganaderiaId,@PathVariable UUID animalId,@AuthenticationPrincipal IdentidadAutenticada i){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(listar.ejecutar(i.usuarioId(),ganaderiaId,animalId).stream().map(Evento::de).toList());}
 record Solicitud(UUID operationId,UUID eventId,Integer schemaVersion,String tipo,LocalDate fecha,String estadoGestacion,LocalDate fechaProbableParto,UUID reproductorAnimalId,String responsable,String observaciones){SolicitudEventoReproductivo dominio(UUID g,UUID a){try{return new SolicitudEventoReproductivo(g,a,eventId,operationId,schemaVersion==null?0:schemaVersion,TipoEventoReproductivo.valueOf(tipo),fecha,estadoGestacion==null?null:EstadoGestacion.valueOf(estadoGestacion),fechaProbableParto,reproductorAnimalId,responsable,observaciones);}catch(Exception x){throw new DatoReproductivoInvalidoException("tipo");}}}
 record Resultado(UUID operationId,UUID eventId,String resultado,Instant confirmadoEn){}
 record Evento(UUID eventId,String tipo,LocalDate fecha,String estadoGestacion,LocalDate fechaProbableParto,UUID reproductorAnimalId,String responsable,String observaciones,Instant creadoEn){static Evento de(EventoReproductivo e){return new Evento(e.id(),e.tipo().name(),e.fecha(),e.estadoGestacion()==null?null:e.estadoGestacion().name(),e.fechaProbableParto(),e.reproductorAnimalId(),e.responsable(),e.observaciones(),e.creadoEn());}}
}
